import{_ as s,o as a,c as e,a0 as o}from"./chunks/framework.DCluYYrN.js";const c=JSON.parse('{"title":"App Profile","description":"","frontmatter":{},"headers":[],"relativePath":"zh_TW/guide/app-profile.md","filePath":"zh_TW/guide/app-profile.md"}'),t={name:"zh_TW/guide/app-profile.md"};function l(p,i,n,h,r,d){return a(),e("div",null,[...i[0]||(i[0]=[o(`<h1 id="app-profile" tabindex="-1">App Profile <a class="header-anchor" href="#app-profile" aria-label="Permalink to &quot;App Profile {#app-profile}&quot;">​</a></h1><p>App Profile 是 KernelSU 提供的一種針對各種應用程式自訂其使用配置的機制。</p><p>對於授予了 root 權限（即可以使用 <code>su</code>）的應用程式來說，App Profile 也可以稱為 Root Profile，它可以自訂 <code>su</code> 的 <code>uid</code>、<code>gid</code>、<code>groups</code>、<code> capabilities</code> 以及 <code>SELinux context</code> 規則，從而限制 root 使用者的權限。 例如可以針對防火牆應用程式僅授予網路權限，而不授予檔案存取權限，針對凍結類別應用程式僅授予 shell 權限而不是直接給 root ；透過最小化權限原則<strong>把權力關進籠子裡</strong>。</p><p>對於沒有被授予 root 權限的普通應用，App Profile 可以控制核心以及模組系統對此應用的行為；例如是否需要針對此應用程式卸載模組造成的修改等。核心和模組系統可以透過此配置決定是否要做一些類似「隱藏痕跡」類別的操作。</p><h2 id="root-profile" tabindex="-1">Root Profile <a class="header-anchor" href="#root-profile" aria-label="Permalink to &quot;Root Profile {#root-profile}&quot;">​</a></h2><h3 id="uid-gid-and-groups" tabindex="-1">UID、GID 和 groups <a class="header-anchor" href="#uid-gid-and-groups" aria-label="Permalink to &quot;UID、GID 和 groups {#uid-gid-and-groups}&quot;">​</a></h3><p>Linux 系統中有使用者和群組兩個概念。每個使用者都有一個使用者 ID(UID)，一個使用者可以屬於多個群組，每個群組也有群組 ID(GID)。此 ID 用於識別系統的使用者並確定使用者可以存取哪些系統資源。</p><p>UID 為 0 的使用者稱為 root 使用者，GID 為 0 的群組稱為 root 群組；root 使用者群組通常擁有系統的最高權限。</p><p>對於 Android 系統來說，每個應用程式都是一個單獨的使用者（不考慮 share uid 的情況），擁有一個唯一的 UID。例如 <code>0</code> 是 root 使用者，<code>1000</code> 是 <code>system</code>，<code>2000</code> 是 ADB shell，10000-19999 的是一般使用者。</p><div class="info custom-block"><p class="custom-block-title">補充</p><p>此處的 UID 跟 Android 系統的多使用者，或者說工作資料（Work Profile），是不同概念。工作資料實際上是對 UID 進行分片實現的，例如 10000-19999 是主使用者，110000-119999 是工作資料；他們中的任何一個普通應用都擁有自己獨有的 UID。</p></div><p>每一個應用程式可以有若干個群組，GID 是其主要的群組，通常與 UID 一致；其他的群組稱為補充群組(groups)。某些權限是透過群組控制的，例如網路訪問，藍牙等。</p><p>例如，如果我們在 ADB shell 中執行 <code>id</code> 指令，會得到以下輸出：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">oriole:/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">id</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">uid</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">2000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shell</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) gid</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">2000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shell</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) groups</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">2000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shell</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,1004</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">input</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,1007</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,1011</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,1015</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdcard_rw</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,1028</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdcard_r</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,1078</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ext_data_ww</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">(ext_obb_rw</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),3001(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">net_bt_admin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),3002(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">net_bt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),3003(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">inet</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),3006(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">net_bw_stats</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),3009(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">readproc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),3011(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uhid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),3012(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">readreadtracefs:s05:</span></span></code></pre></div><p>其中，UID 為<code>2000</code>，GID 也即主要組 ID 也為 <code>2000</code>；除此之外它還在許多補充組裡面，例如 <code>inet</code> 組代表可以創建 <code>AF_INET</code> 和 <code>AF_INET6</code> 的 socket（存取網路），<code>sdcard_rw</code> 代表可以讀寫 sdcard 等。</p><p>KernelSU 的 Root Profile 可以自訂執行 <code>su</code> 後 root 程式的 UID, GID 和 groups。例如，你可以設定某個 root 應用程式的Root Profile 其UID 為<code>2000</code>，這表示此應用程式在使用<code>su</code> 的時候，它的實際權限是ADB Shell 等級；你可以去掉groups 中的<code>inet</code> ，這樣這個<code>su</code> 就無法存取網路。</p><div class="tip custom-block"><p class="custom-block-title">注意</p><p>App Profile 只是控制 root 應用程式使用 <code>su</code> 後的權限，它並非控制應用程式本身的權限！如果應用程式本身申請了網路存取權限，那麼它即使不使用 <code>su</code> 也可以存取網路；為 <code>su</code> 去掉 <code>inet</code> 群組只是讓 <code>su</code> 無法存取網路。</p></div><p>與應用程式透過 <code>su</code> 主動切換使用者或群組不同，Root Profile 是在核心中強制實施的，不依賴 root 應用程式的自覺行為，<code>su</code> 權限的授予完全取決於使用者而非開發者。</p><h3 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities {#capabilities}&quot;">​</a></h3><p>Capabilities 是 Linux 的一種分權機制。</p><p>傳統的 UNIX 系統為了執行權限檢查，將流程分為兩類：特權程式（其等效使用者 ID 為 0，稱為超級使用者或 root）和非特權程式（其等效 UID 為非零）。特權程式會繞過所有核心權限檢查，而非特權程式則根據其憑證（通常是等校 UID、等效 GID 和補充群組清單）進行完整的權限檢查。</p><p>從 Linux 2.2開始，Linux 將傳統上與超級使用者關聯的特權分解為獨立的單元，稱為 Capabilities（有的也翻譯為「權能」），它們可以獨立啟用和停用。</p><p>每一個 Capability 代表一個或一類權限。例如 <code>CAP_DAC_READ_SEARCH</code> 就代表是否有能力繞過檔案讀取權限檢查和目錄讀取和執行權限檢查。如果一個有效 UID 為 <code>0</code> 的使用者（root 使用者）沒有 <code>CAP_DAC_READ_SEARCH</code> 或更高 Capalities，這表示即使它是 root 也不能​​隨意讀取檔案。</p><p>KernelSU 的 Root Profile 可以自訂執行 <code>su</code> 後 root 程式的 Capabilities，從而實現只授予「部分 root 權限」。與上面介紹的UID, GID 不同，某些 root 應用就是需要 <code>su</code> 後 UID 是 <code>0</code>，此時我們可以透過限制這個 UID 為 <code>0</code> 的 root 使用者的 Capabilities，就可以限制它能夠執行的操作。</p><div class="tip custom-block"><p class="custom-block-title">強烈建議</p><p>Linux 的 Capability <a href="https://man7.org/linux/man-pages/man7/capabilities.7.html" target="_blank" rel="noreferrer">官方文件</a>詳細解釋了每一項 Capability 所代表的能力，如果你想要自訂Capabilities，請務必先閱讀此文件。</p></div><h3 id="selinux" tabindex="-1">SELinux <a class="header-anchor" href="#selinux" aria-label="Permalink to &quot;SELinux {#selinux}&quot;">​</a></h3><p>SELinux 是一種強大的強制權限存取控制（MAC）機制。它按照<strong>預設拒絕</strong>的原則運作：任何未經明確允許的行為都會被拒絕。</p><p>SELinux 可依兩種全域模式運作：</p><ol><li>寬容模式：權限拒絕事件會被記錄下來，但不會被強制執行。</li><li>強制模式：權限拒絕事件會被記錄下來<strong>並且</strong>強制執行。</li></ol><div class="warning custom-block"><p class="custom-block-title">警告</p><p>現代的 Android 系統極度依賴 SELinux 來保障整個系統的安全性，我們強烈建議您不要使用任何以「寬容模式」運作的自訂系統，因為那樣與裸奔沒什麼區別。</p></div><p>SELinux 的完整概念比較複雜，我們這裡不打算講解它的具體運作方式，建議你先透過以下資料來了解其運作原理：</p><ol><li><a href="https://en.wikipedia.org/wiki/Security-Enhanced_Linux" target="_blank" rel="noreferrer">wikipedia</a></li><li><a href="https://www.redhat.com/en/topics/linux/what-is-selinux" target="_blank" rel="noreferrer">Redhat: what-is-selinux</a></li><li><a href="https://wiki.archlinux.org/title/SELinux" target="_blank" rel="noreferrer">ArchLinux: SELinux</a></li></ol><p>KernelSU 的 Root Profile 可以自訂執行 <code>su</code> 後 root 程式的 SELinux context，並且可以針對這個 context 設定特定的存取控制規則，從而更精細地控制 root 權限。</p><p>通常情況下，應用程式執行 <code>su</code> 後，會將進程切換到一個<strong>不受任何限制</strong> 的 SELinux 域，例如<code>u:r:ksu:s0</code>，透過 Root Profile，我們可以將它切換到一個自訂的作用域，例如 <code>u:r:app1:s0</code>，然後為這個作用域制定一系列規則：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">enforce</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">typeattribute</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mlstrustedsubject</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span></span></code></pre></div><p>注意：此處的 <code>allow app1 * * *</code> 僅僅作為示範方便而使用，實際過程中不應使用這個規則，因為它跟寬容模式區別不大。</p><h3 id="escalation" tabindex="-1">逃逸 <a class="header-anchor" href="#escalation" aria-label="Permalink to &quot;逃逸 {#escalation}&quot;">​</a></h3><p>如果 Root Profile 的配置不合理，那麼可能會發生逃逸的情況：Root Profile 的限制會意外失效。</p><p>例如，如果你為ADB shell 使用者設定允許root 權限（這是相當常見的情況）；然後你給某個普通應用程式允許 root 權限，但是配置它的 root profile 中的 UID 為 2000（ADB shell 使用者的UID）；那麼此時，這個 App 可以透過執行兩次 <code>su</code> 來獲得完整的root 權限：</p><ol><li>第一次執行 <code>su</code>，由於 App Profile 強制生效，會正常切換到 UID 為 <code>2000</code> (adb shell) 而非 <code>0</code> (root)。</li><li>第二次執行 <code>su</code>，由於此時它 UID 是 <code>2000</code>，而你給 <code>2000</code> (adb shell) 配置了允許 root，它會獲得完整的 root 權限！</li></ol><div class="tip custom-block"><p class="custom-block-title">提示</p><p>你可以在自訂 <code>App Profile</code> 中啟用 <code>NO_NEW_PRIVS</code> 標誌。</p><p>這樣可以防止該進程再次透過 <code>su</code> 命令逃逸並提升權限。</p><p>但是，此標誌<strong>僅</strong>阻止 KernelSU 為該程序提升權限，它仍然可以利用其他 Linux 機制來逃逸。 因此，請務必注意你的權限設定。</p></div><h2 id="non-root-profile" tabindex="-1">Non Root Profile <a class="header-anchor" href="#non-root-profile" aria-label="Permalink to &quot;Non Root Profile {#non-root-profile}&quot;">​</a></h2><h3 id="umount-modules" tabindex="-1">卸載模組 <a class="header-anchor" href="#umount-modules" aria-label="Permalink to &quot;卸載模組 {#umount-modules}&quot;">​</a></h3><p>KernelSU 提供了一種無須直接修改系統分區的方式 (systemless) 來修改系統分區，這是透過掛載 overlayfs 來實現的。但有些情況下，App 可能會對這種行為比較敏感；因此，我們可以透過設定「卸載模組」來卸載掛載在這些應用程式上的模組。</p><p>另外，KernelSU 管理器的設定介面還提供了一個「預設卸載模組」的開關，這個開關預設是<strong>開啟</strong>的，這表示<strong>如果不對應用程式做額外的設定</strong>，預設情況下 KernelSU 或某些模組會對此應用程式執行卸載操作。當然，如果你不喜歡這個設定或這個設定會影響某些 App，你可以有以下選擇：</p><ol><li>保持「預設卸載模組」的開關，然後針對不需要「卸載模組」的應用程式進行單獨的設置，在 App Profile 中關閉「卸載模組」；（相當於「白名單」）。</li><li>關閉「預設卸載模組」的開關，然後針對需要「卸載模組」的應用程式進行單獨的設置，在 App Profile 中開啟「卸載模組」；（相當於「黑名單」）。</li></ol><div class="info custom-block"><p class="custom-block-title">提示</p><p>KernelSU 在 5.10 及以上內核上，內核無須任何修改就可以卸載模組；但在 5.10 以下的設備上，這個開關僅僅是一個&quot;設定&quot;，KernelSU 本身不會做任何動作，如果你希望在 5.10 以前的內核可以卸載模組，你需要將 <code>path_unmount</code> 函數向後移植到 <code>fs/namespace.c</code>，您可以在<a href="./how-to-integrate-for-non-gki.html#how-to-backport-path_unpount">如何為非 GKI 核心整合 KernelSU</a>獲取更多資訊。一些模組（如 ZygiskNext）也會透過這個設定決定是否需要卸載。</p></div>`,46)])])}const E=s(t,[["render",l]]);export{c as __pageData,E as default};
